class RecentCounter:
    def __init__(self):
        self.times = []                                                    # remember every ping's timestamp, in order

    def ping(self, t):
        self.times.append(t)
        count = 0
        for time in self.times:                                           # rescan ALL pings every time, counting the recent ones
            if time >= t - 3000:
                count += 1
        return count


if __name__ == "__main__":
    rc = RecentCounter()
    print([rc.ping(t) for t in [1, 100, 3001, 3002]])

