import java.util.*;

public class Main {
    class RecentCounter {
        List<Integer> times = new ArrayList<>();                                    // remember every ping's timestamp, in order

        int ping(int t) {
            times.add(t);
            int count = 0;
            for (int time : times) {                                                    // rescan ALL pings every time, counting the recent ones
                if (time >= t - 3000) count++;
            }
            return count;
        }
    }

    public static void main(String[] args) {
        RecentCounter rc = new RecentCounter();
        for (int t : new int[]{1, 100, 3001, 3002}) System.out.println(rc.ping(t));
    }
}

