from collections import deque

class RecentCounter:
    def __init__(self):
        self.queue = deque()                                                # a FIFO queue: oldest ping always at the front

    def ping(self, t):
        self.queue.append(t)                                                # enqueue the new ping
        while self.queue[0] < t - 3000:                                    # evict anything too old from the FRONT
            self.queue.popleft()
        return len(self.queue)                                              # everything remaining is within the last 3000ms


if __name__ == "__main__":
    rc = RecentCounter()
    print([rc.ping(t) for t in [1, 100, 3001, 3002]])

